package com.adib.maintenance;
import android.app.*;import android.view.*;import android.widget.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.ShadowAlertDialog;import java.lang.reflect.*;import java.util.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={28,35}) public class PersonalTaskFormTest {
 MainActivity a;JSONObject old;boolean required;
 @Before public void before()throws Exception{old=AccountSession.user;required=AccountSession.required;AccountSession.user=new JSONObject().put("id","personal-form-test").put("role","admin");AccountSession.required=true;a=Robolectric.buildActivity(MainActivity.class).get();set("mode","personal");set("taskOptions",new JSONObject().put("personal",new JSONObject().put("assignees",new JSONObject().put("options",new JSONArray().put("Araz")))));set("plans",new JSONArray().put(new JSONObject().put("id","bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb").put("name","ADIB")));set("equipment",new JSONArray().put(new JSONObject().put("id","aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa").put("name","Konveyer").put("planId","bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb")));}
 @After public void after(){AlertDialog d=ShadowAlertDialog.getLatestAlertDialog();if(d!=null)d.dismiss();AccountSession.user=old;AccountSession.required=required;}
 void set(String n,Object v)throws Exception{Field f=MainActivity.class.getDeclaredField(n);f.setAccessible(true);f.set(a,v);}AlertDialog open(JSONObject task,boolean fresh)throws Exception{Method m=MainActivity.class.getDeclaredMethod("openTaskForm",JSONObject.class,boolean.class);m.setAccessible(true);m.invoke(a,task,fresh);Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();return ShadowAlertDialog.getLatestAlertDialog();}
 void labels(View v,List<String> names){if(v instanceof TextView&&!(v instanceof EditText)&&!(v instanceof Button)&&!(v instanceof CheckBox)){String s=((TextView)v).getText().toString();if(Arrays.asList("Ad","Qovluq","Tapsirildi","Tarix və vaxt","Avadanlıq (isteğe bağlı)","Tapşırıqlar bazası","Plan (avadanlıq olmadan tələb olunur)").contains(s))names.add(s);}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)labels(((ViewGroup)v).getChildAt(i),names);}
 void spinners(View v,List<Spinner> out){if(v instanceof Spinner)out.add((Spinner)v);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)spinners(((ViewGroup)v).getChildAt(i),out);}
 @Test public void freshPersonalTaskUsesSharedOrder()throws Exception{AlertDialog d=open(null,true);List<String> names=new ArrayList<>();labels(d.getWindow().getDecorView(),names);assertEquals(Arrays.asList("Ad","Qovluq","Tapsirildi","Tarix və vaxt","Avadanlıq (isteğe bağlı)","Tapşırıqlar bazası","Plan (avadanlıq olmadan tələb olunur)"),names);assertNotNull(d.getWindow().getDecorView().findViewWithTag("elegant-task-form"));}
 @Test public void personalFormDoesNotExposeEquipmentOrSourceSelectors()throws Exception{AlertDialog d=open(null,true);List<Spinner> fields=new ArrayList<>();spinners(d.getWindow().getDecorView(),fields);assertFalse(fields.stream().anyMatch(s->s instanceof EquipmentSearchSpinner));assertFalse(fields.stream().anyMatch(s->String.valueOf(s.getSelectedItem()).equals("Tasks · Tapşırıqlarım")));assertTrue(fields.stream().anyMatch(s->String.valueOf(s.getSelectedItem()).equals("Qovluq seçilməyib")));}
 @Test public void editedPersonalTaskKeepsFolderFieldWithoutEquipmentAndPlanSelectors()throws Exception{JSONObject t=new JSONObject().put("id","task-personal").put("title","Konveyeri yoxlamaq").put("status","Not started").put("machineId","aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa").put("planId","bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb").put("assignees",new JSONArray().put("Araz"));AlertDialog d=open(t,false);List<Spinner> fields=new ArrayList<>();spinners(d.getWindow().getDecorView(),fields);assertFalse(fields.stream().anyMatch(s->String.valueOf(s.getSelectedItem()).equals("Konveyer")));assertFalse(fields.stream().anyMatch(s->String.valueOf(s.getSelectedItem()).equals("ADIB")));assertTrue(fields.stream().anyMatch(s->String.valueOf(s.getSelectedItem()).equals("Qovluq seçilməyib")));}
 @Test public void equipmentTaskStillHasEquipmentDatabaseAndPlanSelectors()throws Exception{set("mode","equipment");set("currentMachineId","aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa");set("currentPlanId","bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb");AlertDialog d=open(null,true);List<String> names=new ArrayList<>();labels(d.getWindow().getDecorView(),names);assertTrue(names.contains("Avadanlıq (isteğe bağlı)"));assertTrue(names.contains("Tapşırıqlar bazası"));assertTrue(names.contains("Plan (avadanlıq olmadan tələb olunur)"));}
 @Test public void darkFormUsesReadableSharedPalette()throws Exception{set("dark",true);AlertDialog d=open(null,true);View form=d.getWindow().getDecorView().findViewWithTag("elegant-task-form");assertNotNull(form);assertNotEquals(HybridUi.text(true),HybridUi.surface(true));assertNotEquals(HybridUi.text(false),HybridUi.surface(false));}
}
